import{_ as a,o as i,c as t,a2 as l}from"./chunks/framework.BW2T23B9.js";const u=JSON.parse('{"title":"导入 Anki 牌组","description":"","frontmatter":{},"headers":[],"relativePath":"guide/anki-import.md","filePath":"guide/anki-import.md","lastUpdated":null}'),n={name:"guide/anki-import.md"};function o(d,e,c,r,s,p){return i(),t("div",null,[...e[0]||(e[0]=[l(`<h1 id="导入-anki-牌组" tabindex="-1">导入 Anki 牌组 <a class="header-anchor" href="#导入-anki-牌组" aria-label="Permalink to &quot;导入 Anki 牌组&quot;">​</a></h1><p>本页描述 Android 生产路径中的 Official-first 导入。导入对象是 <code>.apkg</code>。<code>.colpkg</code> 和内存示例牌组不属于当前生产导入合同。</p><h2 id="导入前检查" tabindex="-1">导入前检查 <a class="header-anchor" href="#导入前检查" aria-label="Permalink to &quot;导入前检查&quot;">​</a></h2><ul><li>保留原始牌组文件作为备份。</li><li>确认文件可以在桌面 Anki 中打开。</li><li>检查可用存储空间，媒体牌组需要额外空间。</li><li>复杂模板默认不获得网络访问权限。</li><li>大于 2,000 张卡片的牌组可能进入 Lite 组织模式。</li></ul><h2 id="执行路径" tabindex="-1">执行路径 <a class="header-anchor" href="#执行路径" aria-label="Permalink to &quot;执行路径&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>选择 .apkg</span></span>
<span class="line"><span>  -&gt; 解析导入元数据</span></span>
<span class="line"><span>  -&gt; 生成一次 AnkiImportExecutionPlan</span></span>
<span class="line"><span>  -&gt; 写入 Official Collection</span></span>
<span class="line"><span>  -&gt; 建立课程投影</span></span>
<span class="line"><span>  -&gt; 注册 sourceId 与复习入口</span></span></code></pre></div><p>生产 Android 不同时写入 Legacy NoteStore 和 Turna Anki SRS。正式卡片由 Official Collection 持有，正式评分由 Official scheduler 处理。</p><h2 id="组织预览" tabindex="-1">组织预览 <a class="header-anchor" href="#组织预览" aria-label="Permalink to &quot;组织预览&quot;">​</a></h2><p>智能组织尝试从字段与标签中读取以下信息：</p><ul><li>Unit、Chapter、Section、单元、章。</li><li>Lesson、Topic、Subunit、课、节。</li><li><code>unit::</code>、<code>chapter:</code>、<code>单元::</code> 等标签。</li></ul><p>字段优先于标签。无有效元数据时使用 deck 名和稳定分块。关闭智能组织后，应保留旧的确定性分组行为。</p><h2 id="notetype-映射" tabindex="-1">Notetype 映射 <a class="header-anchor" href="#notetype-映射" aria-label="Permalink to &quot;Notetype 映射&quot;">​</a></h2><p>导入预览可将 notetype 映射到：</p><p><code>ankiCard</code>、<code>wordEntry</code>、<code>expression</code>、<code>fillBlank</code>、<code>typeAnswer</code>、<code>listenPick</code>、<code>cloze</code>、<code>multipleChoice</code>、<code>multiSelect</code>。</p><p>操作顺序：</p><ol><li>检查自动识别类型。</li><li>检查 front / back 字段索引。</li><li>查看首张 note 的文本预览。</li><li>必要时手动覆盖。</li><li>配置 AI 时可请求批量识别；AI 输出仍需人工确认。</li></ol><h2 id="full-与-lite" tabindex="-1">Full 与 Lite <a class="header-anchor" href="#full-与-lite" aria-label="Permalink to &quot;Full 与 Lite&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>默认条件</th><th>课程投影</th></tr></thead><tbody><tr><td>Full</td><td>少于 2,000 卡</td><td>生成完整 Section、Unit、Lesson</td></tr><tr><td>Lite</td><td>至少 2,000 卡</td><td>生成轻量 Section shell，正式复习走保真路径</td></tr></tbody></table><p>阈值用于限制课程树规模，不改变牌组中的卡片总数。</p><h2 id="调度继承" tabindex="-1">调度继承 <a class="header-anchor" href="#调度继承" aria-label="Permalink to &quot;调度继承&quot;">​</a></h2><p>导入预览可以提供三种策略：</p><ul><li>保留 Anki 调度。</li><li>保留复习历史并建立 Turna FSRS 状态。</li><li>全部作为新卡。</li></ul><p>Official 生产路径应优先保持 Official 所有权。策略页必须显示受影响卡片数与历史条数。</p><h2 id="失败处理" tabindex="-1">失败处理 <a class="header-anchor" href="#失败处理" aria-label="Permalink to &quot;失败处理&quot;">​</a></h2><p>导入失败时不要重复快速点击导入。先检查错误发生在解析、Official runtime、媒体复制还是课程投影阶段。媒体复制可 best-effort；Collection 写入失败必须明确回滚或标记失败。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/docs/guide/anki">Anki 集成</a></li><li><a href="/docs/guide/anki-rendering">卡片渲染与网络隔离</a></li><li><a href="/docs/guide/troubleshooting#anki">故障排查</a></li></ul>`,27)])])}const f=a(n,[["render",o]]);export{u as __pageData,f as default};
